use serde::{Deserialize, Serialize};
use std::collections::HashMap;
#[doc = " Extracts a single declaration from a `syn::Item`."]
#[doc = " Returns `Some(ExtractedDecl)` if the item is a supported declaration type, `None` otherwise."]
pub fn extract_single_declaration(item: &Item, item_count: usize) -> Option<ExtractedDecl> {
    let content_token_stream = item.to_token_stream();
    let (ast_depth, ast_node_count) = calculate_ast_metrics(item);
    let output_hash = {
        let mut hasher = Sha256::new();
        hasher.update(content_token_stream.to_string());
        format!("{:x}", hasher.finalize())
    };
    let metadata = ExtractedDeclMetadata {
        ast_depth,
        ast_node_count,
        output_hash: Some(output_hash),
        inputs_hash: None,
        rings_of_sizes: Vec::new(),
        zkp_witness_hash: None,
    };
    let extracted_decl_base = |name: String, kind: String| ExtractedDecl {
        name,
        kind,
        content: content_token_stream.clone(),
        metadata,
    };
    match item {
        Item::Fn(item_fn) => Some(extracted_decl_base(
            item_fn.sig.ident.to_string(),
            "fn".to_string(),
        )),
        Item::Struct(item_struct) => Some(extracted_decl_base(
            item_struct.ident.to_string(),
            "struct".to_string(),
        )),
        Item::Enum(item_enum) => Some(extracted_decl_base(
            item_enum.ident.to_string(),
            "enum".to_string(),
        )),
        Item::Const(item_const) => Some(extracted_decl_base(
            item_const.ident.to_string(),
            "const".to_string(),
        )),
        Item::Static(item_static) => Some(extracted_decl_base(
            item_static.ident.to_string(),
            "static".to_string(),
        )),
        Item::Trait(item_trait) => Some(extracted_decl_base(
            item_trait.ident.to_string(),
            "trait".to_string(),
        )),
        Item::Impl(item_impl) => {
            let name = if let Some((_, path, _)) = &item_impl.trait_ {
                let trait_name = path
                    .to_token_stream()
                    .to_string()
                    .replace("::", "_")
                    .replace(" ", "")
                    .replace("<", "_")
                    .replace(">", "_")
                    .replace("(", "_")
                    .replace(")", "_")
                    .replace(",", "_")
                    .replace("'", "_")
                    .chars()
                    .filter(|c| c.is_alphanumeric() || *c == '_')
                    .collect::<String>();
                format!("impl_for_{}", trait_name)
            } else if let syn::Type::Path(type_path) = &*item_impl.self_ty {
                if let Some(segment) = type_path.path.segments.last() {
                    format!("impl_for_{}", segment.ident.to_string())
                } else {
                    format!("impl_{}", item_count)
                }
            } else {
                format!("impl_{}", item_count)
            };
            Some(extracted_decl_base(name, "impl".to_string()))
        }
        Item::Type(item_type) => Some(extracted_decl_base(
            item_type.ident.to_string(),
            "type".to_string(),
        )),
        Item::Union(item_union) => Some(extracted_decl_base(
            item_union.ident.to_string(),
            "union".to_string(),
        )),
        Item::Use(item_use) => {
            println!(
                "Skipping top-level use statement in splitting: {}",
                item_use.to_token_stream()
            );
            None
        }
        Item::Macro(item_macro) => {
            let macro_name = item_macro
                .mac
                .path
                .segments
                .last()
                .map_or("unknown_macro".to_string(), |s| s.ident.to_string());
            Some(extracted_decl_base(macro_name, "macro".to_string()))
        }
        Item::Mod(item_mod) => {
            let mod_name = item_mod.ident.to_string();
            println!("Processing module: {}", mod_name);
            Some(extracted_decl_base(mod_name, "module".to_string()))
        }
        _ => {
            println!("Skipping unsupported item type: {}", item.to_token_stream());
            None
        }
    }
}
